parameters.text:
=Candidate Resume:
{{ $('Extract Candidate Resume Text').item.json.text }}

Job Description:
{{ $json.text }}

parameters.inputSchema:
{
  "name": "resume_screening_support",
  "description": "Structured, evidence-based screening support for comparing a resume with a job description. Human review required.",
  "type": "object",
  "properties": {
    "candidate_strengths": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Specific job-related strengths supported by the resume."
    },
    "requirement_matches": {
      "type": "array",
      "description": "Required or preferred criteria matched to evidence.",
      "items": {
        "type": "object",
        "properties": {
          "requirement": {
            "type": "string"
          },
          "status": {
            "type": "string",
            "enum": [
              "matched",
              "partially_matched",
              "not_evidenced"
            ]
          },
          "evidence": {
            "type": "string"
          },
          "confidence": {
            "type": "string",
            "enum": [
              "high",
              "medium",
              "low"
            ]
          }
        },
        "required": [
          "requirement",
          "status",
          "evidence",
          "confidence"
        ]
      }
    },
    "evidence_gaps": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Important requirements not evidenced in the supplied documents."
    },
    "verification_questions": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Questions or checks for human review."
    },
    "screening_summary": {
      "type": "string",
      "description": "Brief factual summary of alignment and uncertainty."
    },
    "human_review_required": {
      "type": "boolean",
      "description": "Always true for this workflow."
    }
  },
  "required": [
    "candidate_strengths",
    "requirement_matches",
    "evidence_gaps",
    "verification_questions",
    "screening_summary",
    "human_review_required"
  ]
}
